using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using System.Collections.Concurrent;
namespace DropShip.Core;
public sealed class V2Service(PairBook book,TransferRepository repository) {
    readonly object gate=new();public event Action<ReceiveProgress>? Progress;public event Action<TransferReceipt>? Completed;public event Action<string>? Failed;
    public object Health=>new{service="DropShip",protocol=2,version="0.6.0",deviceId=book.OwnId,name=book.OwnName(),approvalRequired=true,receiveReady=repository.ReadinessIssue==null,receiveMessage=repository.ReadinessIssue??""};
    public (int,object) Handle(string method,string path,Dictionary<string,string> headers,byte[] body){lock(gate){
        if(method=="GET"&&path=="/v2/health")return(200,Health);
        if(method=="POST"&&path=="/v2/pair/request"){using var doc=JsonDocument.Parse(body);var p=doc.RootElement;var t=book.Request(p.GetProperty("deviceId").GetString()!,p.GetProperty("name").GetString()!,p.GetProperty("nonce").GetString()!);return(200,new{requestId=t.RequestId,code=t.Code,deviceId=book.OwnId,name=book.OwnName(),status=t.Status});}
        if(method=="GET"&&path.StartsWith("/v2/pair/"))return(200,book.Poll(path[9..],headers.GetValueOrDefault("X-DropShip-Nonce","")));
        var owner=book.Authenticate(headers);
        try {
        if(method=="POST"&&path=="/v2/transfers"){var spec=JsonSerializer.Deserialize<TransferSpec>(body,V2Json.Options)??throw new V2Error(400,"파일 정보가 없습니다.");return(200,Status(repository.Begin(owner,spec)));}
        if(path.StartsWith("/v2/transfers/")){var tail=path[14..];var parts=tail.Split('/');var id=parts[0];if(parts.Length==1&&method=="GET")return(200,Status(repository.Load(owner,id)));
            if(parts.Length==1&&method=="PATCH"){if(!long.TryParse(headers.GetValueOrDefault("X-DropShip-Offset",""),out var offset))throw new V2Error(400,"전송 위치가 없습니다.");var state=repository.Chunk(owner,id,offset,body,headers.GetValueOrDefault("X-DropShip-Chunk-SHA256",""));Progress?.Invoke(new(state.Spec.RelativePath,state.Offset,state.Spec.Size));return(200,Status(state));}
            if(parts.Length==2&&parts[1]=="commit"&&method=="POST"){var state=repository.Load(owner,id);bool fresh=state.Receipt==null;var receipt=repository.Commit(owner,id);if(fresh)Completed?.Invoke(receipt);return(201,new{name=receipt.Name,size=receipt.Size,sha256=receipt.Sha256,path=receipt.Path});}
        }throw new V2Error(404,"지원하지 않는 전송 경로입니다.");
        }catch(Exception e){Failed?.Invoke((e is V2Error v?$"HTTP {v.Code} · ":e.GetType().Name+" · ")+e.Message);throw;}
    }}
    static object Status(TransferState s)=>new{offset=s.Offset,complete=s.Receipt!=null,receipt=s.Receipt==null?null:new{name=s.Receipt.Name,size=s.Receipt.Size,sha256=s.Receipt.Sha256,path=s.Receipt.Path}};
    public int ClearIncomplete(){lock(gate)return repository.ClearIncomplete();}
}
public sealed class ReceiverV2(V2Service service,int port=8765):IAsyncDisposable {
    readonly CancellationTokenSource stop=new();readonly TcpListener listener=new(IPAddress.Any,port);readonly SemaphoreSlim slots=new(4);readonly ConcurrentDictionary<TcpClient,Task> clients=new();Task? accept;
    public void Start(){listener.Start(8);accept=Accept();}
    async Task Accept(){try{while(!stop.IsCancellationRequested){await slots.WaitAsync(stop.Token);TcpClient tcp;try{tcp=await listener.AcceptTcpClientAsync(stop.Token);}catch{slots.Release();throw;}var ready=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);clients[tcp]=Run(tcp,ready.Task);ready.SetResult();}}catch(Exception)when(stop.IsCancellationRequested){}}
    async Task Run(TcpClient tcp,Task ready){await ready;using var timeout=CancellationTokenSource.CreateLinkedTokenSource(stop.Token);timeout.CancelAfter(TimeSpan.FromSeconds(60));try{
        var stream=tcp.GetStream();var request=(await Line(stream,timeout.Token)).Split(' ');if(request.Length!=3||request[2]!="HTTP/1.1")throw new V2Error(400,"요청 형식이 올바르지 않습니다.");
        var headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);int count=0;while(true){var line=await Line(stream,timeout.Token);count+=line.Length;if(count>16384||headers.Count>40)throw new V2Error(431,"요청 정보가 너무 큽니다.");if(line=="")break;int at=line.IndexOf(':');if(at<=0||!headers.TryAdd(line[..at],line[(at+1)..].Trim()))throw new V2Error(400,"중복되거나 잘못된 요청 정보입니다.");}
        if(headers.ContainsKey("Transfer-Encoding"))throw new V2Error(400,"고정 크기 요청만 지원합니다.");long length=0;if(headers.TryGetValue("Content-Length",out var raw)&&!long.TryParse(raw,out length))throw new V2Error(400,"요청 크기가 올바르지 않습니다.");int limit=request[0]=="PATCH"?1048576:16384;if(length<0||length>limit)throw new V2Error(413,"요청 크기가 너무 큽니다.");var body=new byte[(int)length];await stream.ReadExactlyAsync(body,timeout.Token);var(code,value)=service.Handle(request[0],request[1],headers,body);await Respond(stream,code,value,timeout.Token);
    }catch(Exception e){int code=e is V2Error error?error.Code:400;string message=e is V2Error?e.Message:e is IOException?"저장 공간이나 연결을 확인해 주세요.":"요청을 처리하지 못했습니다.";try{using var shortTimeout=new CancellationTokenSource(TimeSpan.FromSeconds(3));await Respond(tcp.GetStream(),code,new{error=message},shortTimeout.Token);}catch{}}
    finally{tcp.Dispose();slots.Release();clients.TryRemove(tcp,out _);}}
    static async Task<string> Line(Stream stream,CancellationToken ct){var b=new List<byte>();var one=new byte[1];while(b.Count<=4096){if(await stream.ReadAsync(one,ct)==0)throw new EndOfStreamException();if(one[0]==10){if(b.Count==0||b[^1]!=13)throw new V2Error(400,"요청 형식이 올바르지 않습니다.");return Encoding.ASCII.GetString(b.ToArray(),0,b.Count-1);}b.Add(one[0]);}throw new V2Error(431,"요청 정보가 너무 큽니다.");}
    static async Task Respond(Stream stream,int code,object value,CancellationToken ct){var bytes=JsonSerializer.SerializeToUtf8Bytes(value,V2Json.Options);var head=Encoding.ASCII.GetBytes($"HTTP/1.1 {code} {(code<300?"OK":"Error")}\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: {bytes.Length}\r\nConnection: close\r\n\r\n");await stream.WriteAsync(head,ct);await stream.WriteAsync(bytes,ct);}
    public async ValueTask DisposeAsync(){stop.Cancel();listener.Stop();foreach(var tcp in clients.Keys)tcp.Dispose();if(accept!=null)await accept;await Task.WhenAll(clients.Values);slots.Dispose();stop.Dispose();}
}
public sealed class ClientV2(PairBook book):IDisposable {
    readonly HttpClient http=new(new SocketsHttpHandler{UseProxy=false,AllowAutoRedirect=false,ConnectTimeout=TimeSpan.FromSeconds(5)}){Timeout=Timeout.InfiniteTimeSpan};
    public async Task<JsonElement> Request(DeviceEndpoint ep,string method,string path,object? json,CancellationToken ct,string? target=null,byte[]? body=null,Dictionary<string,string>? extra=null){
        using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(60));using var req=new HttpRequestMessage(new HttpMethod(method),ep.Uri(path)){Version=HttpVersion.Version11};req.Headers.ExpectContinue=false;
        if(target!=null){var device=book.Find(target)??throw new V2Error(403,"먼저 기기 연결을 승인해 주세요.");req.Headers.Add("X-DropShip-Device",book.OwnId);req.Headers.Add("X-DropShip-Target",target);req.Headers.Add("X-DropShip-Token",device.Token);}
        if(extra!=null)foreach(var(k,v)in extra)req.Headers.Add(k,v);if(body!=null||json!=null)req.Content=new ByteArrayContent(body??JsonSerializer.SerializeToUtf8Bytes(json,V2Json.Options));
        using var response=await http.SendAsync(req,HttpCompletionOption.ResponseHeadersRead,timeout.Token);await using var stream=await response.Content.ReadAsStreamAsync(timeout.Token);using var memory=new MemoryStream();byte[] buffer=new byte[4096];int n;while((n=await stream.ReadAsync(buffer,timeout.Token))>0){if(memory.Length+n>16384)throw new V2Error(400,"응답이 너무 큽니다.");memory.Write(buffer,0,n);}using var doc=JsonDocument.Parse(memory.ToArray());var data=doc.RootElement.Clone();if(!response.IsSuccessStatusCode)throw new V2Error((int)response.StatusCode,data.TryGetProperty("error",out var err)?err.GetString()!:"전송을 완료하지 못했습니다.");return data;
    }
    public async Task<RemoteInfo> Inspect(DeviceEndpoint ep,CancellationToken ct){var j=await Request(ep,"GET","/v2/health",null,ct);if(j.GetProperty("service").GetString()!="DropShip"||j.GetProperty("protocol").GetInt32()!=2)throw new V2Error(400,"양쪽에서 v0.5 이상을 실행해 주세요.");var id=j.GetProperty("deviceId").GetString()!;if(!V2Json.Hex(id,32)||id==book.OwnId)throw new V2Error(400,"다른 기기를 선택해 주세요.");return new(id,j.GetProperty("name").GetString()??"DropShip",!j.TryGetProperty("receiveReady",out var ready)||ready.GetBoolean(),j.TryGetProperty("receiveMessage",out var message)?message.GetString()??"":"");}
    public async Task<string> Health(DeviceEndpoint ep,CancellationToken ct)=>(await Inspect(ep,ct)).Id;
    public async Task Pair(DeviceEndpoint ep,Action<string,string> showCode,CancellationToken ct){var nonce=Guid.NewGuid().ToString("N");var start=await Request(ep,"POST","/v2/pair/request",new{deviceId=book.OwnId,name=book.OwnName(),nonce},ct);var requestId=start.GetProperty("requestId").GetString()!;var remote=start.GetProperty("deviceId").GetString()!;showCode(start.GetProperty("name").GetString()!,start.GetProperty("code").GetString()!);using var duration=CancellationTokenSource.CreateLinkedTokenSource(ct);duration.CancelAfter(TimeSpan.FromMinutes(2));while(true){await Task.Delay(1000,duration.Token);var j=await Request(ep,"GET","/v2/pair/"+requestId,null,duration.Token,extra:new(){{"X-DropShip-Nonce",nonce}});if(j.GetProperty("deviceId").GetString()!=remote)throw new V2Error(403,"다른 기기가 응답했습니다.");var state=j.GetProperty("status").GetString();if(state=="rejected")throw new V2Error(403,"상대 기기에서 연결을 거절했습니다.");if(state=="approved"){book.Put(remote,j.GetProperty("name").GetString()!,j.GetProperty("token").GetString()!);return;}}}
    public async Task<TransferReceipt> Send(DeviceEndpoint ep,string target,string localPath,string relative,string transferId,string batchId,bool directory,IProgress<TransferProgress> progress,CancellationToken ct){
        V2Json.PathName(relative);var remote=await Inspect(ep,ct);if(remote.Id!=target)throw new V2Error(403,"선택한 기기의 주소가 바뀌었습니다. 다시 검색해 주세요.");if(!remote.ReceiveReady)throw new V2Error(409,remote.ReceiveMessage==""?"받는 기기에서 수신 폴더를 설정해 주세요.":remote.ReceiveMessage);
        await using var file=directory?null:new FileStream(localPath,FileMode.Open,FileAccess.Read,FileShare.Read,131072,true);long total=file?.Length??0;progress.Report(new("원본 확인",0,total));var hash=directory?V2Json.Hash([]):Convert.ToHexString(await System.Security.Cryptography.SHA256.HashDataAsync(file!,ct)).ToLowerInvariant();if(file!=null)file.Position=0;
        var spec=new TransferSpec(transferId,batchId,relative,total,hash,directory);var status=await Request(ep,"POST","/v2/transfers",spec,ct,target);if(!status.GetProperty("complete").GetBoolean()&&!directory){var offset=status.GetProperty("offset").GetInt64();if(offset<0||offset>total)throw new V2Error(409,"수신 위치가 올바르지 않습니다.");progress.Report(new(offset>0?"이어보내기":"전송 중",offset,total));file!.Position=offset;var b=new byte[1048576];while(offset<total){int count=(int)Math.Min(b.Length,total-offset);await file.ReadExactlyAsync(b.AsMemory(0,count),ct);var chunk=b.AsSpan(0,count).ToArray();var result=await Request(ep,"PATCH","/v2/transfers/"+transferId,null,ct,target,chunk,new(){{"X-DropShip-Offset",offset.ToString(System.Globalization.CultureInfo.InvariantCulture)},{"X-DropShip-Chunk-SHA256",V2Json.Hash(chunk)}});var next=result.GetProperty("offset").GetInt64();if(next!=offset+count)throw new V2Error(409,"수신 위치가 일치하지 않습니다.");offset=next;progress.Report(new("전송 중",offset,total));}}
        ct.ThrowIfCancellationRequested();progress.Report(new("저장·검증",total,total));var receipt=await Request(ep,"POST","/v2/transfers/"+transferId+"/commit",new{},ct,target);var r=JsonSerializer.Deserialize<TransferReceipt>(receipt,V2Json.Options)!;if(r.Size!=total||r.Sha256!=hash||string.IsNullOrEmpty(r.Name)||string.IsNullOrEmpty(r.Path))throw new V2Error(422,"수신 검증 결과가 일치하지 않습니다.");return r;
    }
    public void Dispose()=>http.Dispose();
}
